#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using State = pair<ll, ll>;

unordered_map<ll, State> memo;

ll cubeRoot(ll n) {
    ll x = cbrt((long double)n);
    while ((__int128)(x + 1) * (x + 1) * (x + 1) <= n) ++x;
    while ((__int128)x * x * x > n) --x;
    return x;
}

State solve(ll m) {
    if (m == 0) return {0, 0};

    auto it = memo.find(m);
    if (it != memo.end()) return it->second;

    ll x = cubeRoot(m);
    ll cube = x * x * x;

    State take = solve(m - cube);
    ++take.first;
    take.second += cube;

    State skip = solve(cube - 1);

    return memo[m] = max(take, skip);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll m;
    cin >> m;

    State answer = solve(m);
    cout << answer.first << ' ' << answer.second;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll bestCount = 0;
ll bestSum = 0;

ll cube(ll x) {
    return x * x * x;
}

ll cubeRoot(ll x) {
    ll r = static_cast<ll>(cbrt(static_cast<long double>(x)));
    while ((i128)(r + 1) * (r + 1) * (r + 1) <= x) ++r;
    while ((i128)r * r * r > x) --r;
    return r;
}

void solve(ll remaining, ll count, ll sum) {
    if (remaining == 0) {
        if (count > bestCount || (count == bestCount && sum > bestSum)) {
            bestCount = count;
            bestSum = sum;
        }
        return;
    }

    ll x = cubeRoot(remaining);
    ll x3 = cube(x);

    solve(remaining - x3, count + 1, sum + x3);

    if (x > 1) {
        ll y3 = cube(x - 1);
        solve(x3 - 1 - y3, count + 1, sum + y3);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll m;
    cin >> m;

    solve(m, 0, 0);
    cout << bestCount << ' ' << bestSum;

    return 0;
