            bestSum = sum;
        }
        return;
    }

    ll x = cubeRoot(remaining);
    ll x3 = (ll)cube(x);

    solve(remaining - x3, count + 1, sum + x3);

    if (x > 1) {
        ll y3 = (ll)cube(x - 1);
        solve(x3 - 1 - y3, count + 1, sum + y3);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll m;
    cin >> m;

    solve(m, 0, 0);
    cout << bestCount << ' ' << bestSum;

