#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll cubeRoot(ll n) {
    ll x = static_cast<ll>(cbrt(static_cast<long double>(n)));
    while ((i128)(x + 1) * (x + 1) * (x + 1) <= n) ++x;
    while ((i128)x * x * x > n) --x;
    return x;
}

pair<ll, ll> solve(ll m) {
    if (m < 8) return {m, m};

    ll x = cubeRoot(m);
    ll currentCube = static_cast<ll>((i128)x * x * x);

    auto takeCurrent = solve(m - currentCube);
    ++takeCurrent.first;
    takeCurrent.second += currentCube;

    ll y = x - 1;
    ll smallerCube = static_cast<ll>((i128)y * y * y);

    auto takeSmaller = solve(currentCube - 1 - smallerCube);
    ++takeSmaller.first;
    takeSmaller.second += smallerCube;

    return max(takeCurrent, takeSmaller);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll m;
    cin >> m;

    auto answer = solve(m);
    cout << answer.first << ' ' << answer.second;
    return 0;
}

